// app/[locale]/testimonial-submit/page.tsx
// -----------------------------------------
// Professional testimonial page, reachable only through a time-limited,
// single-use HMAC invitation link generated by POST /api/admin/testimonial-invite
// (/[locale]/testimonial-submit?invite=<hmac-hex>&exp=<unix-timestamp>).
// The raw TESTIMONIAL_SUBMIT_TOKEN never appears in a URL; a missing, invalid,
// forged or missing link answers 404 (the page's existence is not revealed);
// a genuine link that expired or was already used shows a short message so
// the invitee knows to ask for a new one. noindex. Submissions are emailed
// to the site owner through Formhook (app/api/testimonial-submit/route.ts).

import { getTranslations } from "next-intl/server";
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { isInviteUsed, isInviteValid, sessionKeyFor } from "@/lib/security/testimonialInvite";
import TestimonialSubmitForm from "@/components/TestimonialSubmitForm";
import { getSiteUrl } from "@/lib/siteUrl";

// ── Metadata: noindex (private page) ──────────────────────────────────────────
export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<Metadata> {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: "testimonialPage" });
  const siteUrl = getSiteUrl();

  return {
    title: t("metaTitle"),
    // Own description (would otherwise inherit the home page's)
    description: t("metaDescription"),
    // Keep out of search engines
    robots: { index: false, follow: false },
    // Own canonical
    alternates: { canonical: `${siteUrl}/${locale}/testimonial-submit` },
  };
}

// ── Page ───────────────────────────────────────────────────────────────────────

type PageProps = {
  params:      Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
};

export default async function TestimonialSubmitPage({
  params,
  searchParams,
}: PageProps) {
  const { locale: rawLocale } = await params;
  const sp                    = await searchParams;
  const locale: "en" | "fr" | "es" = rawLocale === "fr" ? "fr" : rawLocale === "es" ? "es" : "en";
  const t = await getTranslations({ locale, namespace: "testimonialPage" });

  // ── HMAC invitation link ──────────────────────────────────────────────────
  // ?invite=<hmac-sha256-hex>&exp=<unix-seconds>, where
  // invite = HMAC-SHA256(TESTIMONIAL_SUBMIT_TOKEN, "testimonial-invite:" + exp).
  // Only this time-limited derivative is shared, never the token.
  const secret     = process.env.TESTIMONIAL_SUBMIT_TOKEN ?? "";
  const invite     = typeof sp.invite === "string" ? sp.invite.trim() : "";
  const expStr     = typeof sp.exp    === "string" ? sp.exp.trim()    : "";
  const expUnix    = parseInt(expStr, 10);
  // eslint-disable-next-line react-hooks/purity -- async server component, not a React hook
  const nowSec     = Math.floor(Date.now() / 1000);

  // Genuine link: the signature matches, whatever the current time (checked
  // as of one second before its own expiry). Anything else (no parameters,
  // forged or malformed link, no secret configured) gets a plain 404, like
  // any unknown URL, instead of a 200 "access denied" page.
  const isGenuine = Number.isFinite(expUnix) && isInviteValid(secret, invite, expUnix, (expUnix - 1) * 1000);
  if (!isGenuine) notFound();

  // Genuine, unexpired and unused (single use, lib/security/testimonialInvite.ts).
  let isAuthorized = isInviteValid(secret, invite, expUnix, nowSec * 1000);
  if (isAuthorized && (await isInviteUsed(invite))) isAuthorized = false;

  if (!isAuthorized) {
    return (
      <div className="mx-auto max-w-xl px-4 py-20 text-center">
        <p className="text-4xl">🔒</p>
        {/* Reached only with a genuine invitation that expired or was used */}
        <h1 className="mt-4 text-xl font-semibold">
          {t("expiredTitle")}
        </h1>
        <p className="mt-3 text-sm text-muted">
          {t("expiredBody")}
        </p>
      </div>
    );
  }

  // ── 30-minute HMAC session key bound to this invitation ───────────────────
  // The raw token is never passed to the client component (it would be
  // serialised into the RSC payload). The API re-validates the key.
  const sessionKey = sessionKeyFor(secret, invite);

  return (
    <div className="mx-auto max-w-2xl px-4 py-10">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-semibold">
          {t("title")}
        </h1>
        <p className="mt-2 text-sm text-muted">
          {t("intro")}
        </p>
      </div>

      {/* Form: 30-minute session key, never the raw token */}
      <TestimonialSubmitForm sessionKey={sessionKey} invite={invite} exp={expUnix} locale={locale} />

      {/* Privacy */}
      <p className="mt-8 text-xs text-muted-2">
        {t("privacy")}
      </p>
    </div>
  );
}
